actions.script:
if (!ec.user.isInGroup('ADMIN')) { ec.message.addError('Only the platform administrator can assign tenant plans.'); return }
def today = ec.user.nowTimestamp.toLocalDateTime().toLocalDate()
java.time.LocalDate until
try { until = java.time.LocalDate.parse(accessUntil.toString()) }
catch (Exception e) { ec.message.addError('Enter a valid access end date (YYYY-MM-DD).'); return }
if (until < today || until.year > 9998) { ec.message.addError('The access end date must be today or later, before year 9999.'); return }
def note = reason.toString().trim()
if (!note || note.length() > 500) { ec.message.addError('Enter an assignment reason of 1 to 500 characters.'); return }
def tenant = ec.entity.find('zenith.erp.saas.SaasTenant').condition('tenantId',tenantId).forUpdate(true).one()
if (!tenant || !tenant.organizationPartyId) { ec.message.addError('Tenant not found.'); return }
if (!(tenant.statusId in ['SaasTenantActive','SaasTenantTrial','SaasTenantSuspended'])) {
    ec.message.addError('A cancelled tenant must be reviewed before assigning access.'); return
}
def plan = ec.entity.find('zenith.erp.saas.SaasPlan').condition('planId',newPlanId).one()
if (!plan || plan.isActive != 'Y') { ec.message.addError('Choose an active plan.'); return }
def config = ec.entity.find('zenith.erp.saas.SaasTenantConfig')
    .condition('tenantId',tenantId).condition('configKey','MANUAL_PLAN_SUBSCRIPTION').one()
def current = config?.configValue ? ec.entity.find('zenith.erp.saas.SaasSubscription')
    .condition('subscriptionId',config.configValue).condition('tenantId',tenantId).one() : null
def end = java.sql.Date.valueOf(until)
if (current?.statusId == 'SubActive' && current.planId == newPlanId && current.endDate == end && tenant.statusId == 'SaasTenantActive') {
    subscriptionId = current.subscriptionId
    ec.message.addMessage('This plan and access end date are already assigned.'); return
}
def limits = ec.service.sync().name('zenith.saas.SaasServices.check#UsageLimits')
    .parameters([tenantId:tenantId,planId:newPlanId]).call()
if (ec.message.hasError()) return
if (!limits?.withinLimits) { ec.message.addError('Current usage exceeds this plan: '+(limits?.violations ?: []).join('; ')); return }
// The legacy usage collector counts partyId=orgId, missing tenant members.
def seatIds = new HashSet()
if (tenant.subdomain) seatIds.addAll(ec.entity.find('moqui.security.UserGroupMember')
    .condition('userGroupId','TENANT_'+tenant.subdomain.toUpperCase(java.util.Locale.ROOT))
    .conditionDate('fromDate','thruDate',ec.user.nowTimestamp).list()*.userId)
def memberParties = ec.entity.find('mantle.party.PartyRelationship').condition('toPartyId',tenant.organizationPartyId)
    .condition('toRoleTypeId','OrgInternal').conditionDate('fromDate','thruDate',ec.user.nowTimestamp).list()*.fromPartyId
if (memberParties) seatIds.addAll(ec.entity.find('moqui.security.UserAccount').condition('partyId','in',memberParties).list()*.userId)
if (tenant.adminUserId) seatIds.add(tenant.adminUserId)
def enabledSeats = seatIds ? ec.entity.find('moqui.security.UserAccount').condition('userId','in',new ArrayList(seatIds))
    .list().count { it.disabled != 'Y' } : 0
if (plan.maxUsers > 0 && enabledSeats > plan.maxUsers) {
    ec.message.addError('Current usage exceeds this plan: Users '+enabledSeats+'/'+plan.maxUsers); return
}
if (current?.statusId == 'SubActive' && current.planId == newPlanId) {
    // Extending the same grant retains its original start date and elapsed-day count.
    subscriptionId = current.subscriptionId
    ec.service.sync().name('update#zenith.erp.saas.SaasSubscription')
        .parameters([subscriptionId:subscriptionId,endDate:end,autoRenew:'N']).call()
} else {
    // Retire all live predecessors so stale trials/renewals cannot compete with this grant.
    ec.entity.find('zenith.erp.saas.SaasSubscription').condition('tenantId',tenantId)
        .condition('statusId','in',['SubActive','SubTrial','SubPastDue','SubPaused']).list().each { previous ->
            ec.service.sync().name('update#zenith.erp.saas.SaasSubscription').parameters([
                subscriptionId:previous.subscriptionId,
                statusId:previous.statusId in ['SubPastDue','SubPaused'] ? 'SubCancelled' : 'SubExpired',
                autoRenew:'N',endDate:java.sql.Date.valueOf(today)]).call()
        }
    def created = ec.service.sync().name('create#zenith.erp.saas.SaasSubscription').parameters([
        tenantId:tenantId,planId:newPlanId,statusId:'SubActive',billingCycle:'Manual',
        startDate:java.sql.Date.valueOf(today),endDate:end,autoRenew:'N',amount:0,
        currencyUomId:tenant.currencyUomId]).call()
    if (ec.message.hasError()) return
    subscriptionId = created.subscriptionId
}
ec.service.sync().name('store#zenith.erp.saas.SaasTenantConfig').parameters([
    tenantId:tenantId,configKey:'MANUAL_PLAN_SUBSCRIPTION',configValue:subscriptionId]).call()
ec.service.sync().name('update#zenith.erp.saas.SaasTenant').parameters([
    tenantId:tenantId,planId:newPlanId,statusId:'SaasTenantActive']).call()
ec.service.sync().name('create#zenith.erp.saas.SaasAuditLog').parameters([
    tenantId:tenantId,eventType:'MANUAL_PLAN_ASSIGNED',eventDate:ec.user.nowTimestamp,userId:ec.user.userId,
    description:'Manual access: '+newPlanId+' from '+(current?.statusId == 'SubActive' && current.planId == newPlanId ? current.startDate : today)+' through '+until+'. '+note]).call()
ec.message.addMessage('Plan assigned through '+until+'. No invoice or payment was created.')

if (ec.web != null && !ec.user.isInGroup('ADMIN')) { ec.message.addError('Only the platform administrator can run access expiry.'); return }
def tenant = ec.entity.find('zenith.erp.saas.SaasTenant').condition('tenantId',tenantId).forUpdate(true).one()
def config = ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('tenantId',tenantId)
    .condition('configKey','MANUAL_PLAN_SUBSCRIPTION').one()
if (!tenant || !config?.configValue) return
def sub = ec.entity.find('zenith.erp.saas.SaasSubscription').condition('subscriptionId',config.configValue)
    .condition('tenantId',tenantId).forUpdate(true).one()
def today = java.sql.Date.valueOf(ec.user.nowTimestamp.toLocalDateTime().toLocalDate())
if (!sub || sub.statusId != 'SubActive' || !sub.endDate || sub.endDate >= today) return
ec.service.sync().name('update#zenith.erp.saas.SaasSubscription')
    .parameters([subscriptionId:sub.subscriptionId,statusId:'SubExpired']).call()
if (tenant.statusId == 'SaasTenantActive') ec.service.sync().name('update#zenith.erp.saas.SaasTenant')
    .parameters([tenantId:tenantId,statusId:'SaasTenantSuspended']).call()
ec.service.sync().name('create#zenith.erp.saas.SaasAuditLog').parameters([
    tenantId:tenantId,eventType:'MANUAL_ACCESS_ENDED',eventDate:ec.user.nowTimestamp,
    description:'Manual plan access ended after '+sub.endDate+'. Extend the dated assignment to restore access.']).call()
